<?php
session_start();require_once('dbstring.php');require_once('alumni-utils.php');require_once('online-admission-utils.php');alumni_ensure_tables($con);$message='';$stage=empty($_SESSION['alumni_claim_id'])?'find':'verify';
if(isset($_POST['request_code'])&&alumni_csrf_valid($_POST['csrf']??'')){$identity=trim((string)$_POST['identity']);$stmt=mysqli_prepare($con,"SELECT alumniid,mobile,passwordhash FROM tblalumni WHERE status='active' AND (mobile=? OR email=?) LIMIT 1");mysqli_stmt_bind_param($stmt,'ss',$identity,$identity);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$member=$res?mysqli_fetch_assoc($res):null;mysqli_stmt_close($stmt);$phone=online_admission_normalize_sms_phone($member['mobile']??'');if(!$member){$message='No approved alumni profile was found with those details.';}elseif(!empty($member['passwordhash'])){$message='This profile already has access. Please use Member Sign In.';}elseif($phone===''){$message='A verified mobile number is needed to claim this profile. Please contact AYISEC for help.';}else{$code=(string)random_int(100000,999999);$response='';if(online_admission_sms_gateway_send($phone,'Your AYISEC Alumni access code is '.$code.'. It expires in 15 minutes.',$response)){$stmt=mysqli_prepare($con,'INSERT INTO tblalumniclaimtoken(alumniid,codehash,expiresat) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 15 MINUTE))');$hash=hash('sha256',$code);mysqli_stmt_bind_param($stmt,'ss',$member['alumniid'],$hash);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['alumni_claim_id']=$member['alumniid'];$stage='verify';$message='A six-digit access code was sent to your registered phone.';}else{$message='The access code could not be sent. Please try later or contact AYISEC.';}}}
if(isset($_POST['claim_profile'])&&alumni_csrf_valid($_POST['csrf']??'')){$id=trim((string)($_SESSION['alumni_claim_id']??''));$code=trim((string)$_POST['code']);$password=(string)$_POST['password'];$hash=hash('sha256',$code);$stmt=mysqli_prepare($con,"SELECT tokenid FROM tblalumniclaimtoken WHERE alumniid=? AND codehash=? AND usedat IS NULL AND expiresat>=NOW() ORDER BY tokenid DESC LIMIT 1");mysqli_stmt_bind_param($stmt,'ss',$id,$hash);mysqli_stmt_execute($stmt);$res=mysqli_stmt_get_result($stmt);$token=$res?mysqli_fetch_assoc($res):null;mysqli_stmt_close($stmt);if(!$token||strlen($password)<8){$message='Use a valid unexpired code and a password of at least 8 characters.';}else{$newHash=password_hash($password,PASSWORD_DEFAULT);$stmt=mysqli_prepare($con,'UPDATE tblalumni SET passwordhash=? WHERE alumniid=?');mysqli_stmt_bind_param($stmt,'ss',$newHash,$id);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);mysqli_query($con,'UPDATE tblalumniclaimtoken SET usedat=NOW() WHERE tokenid='.(int)$token['tokenid']);unset($_SESSION['alumni_claim_id']);session_regenerate_id(true);$_SESSION['ALUMNI_MEMBER']=$id;header('location:alumni-community.php');exit();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Claim Alumni Profile</title><style>body{margin:0;background:#f4f7fb;font:16px Arial;color:#172b4d}.card{max-width:470px;margin:70px auto;background:#fff;padding:26px;border-radius:13px;border:1px solid #dce5ed}input{box-sizing:border-box;width:100%;padding:11px;margin:6px 0 14px;border:1px solid #cbd7e4;border-radius:7px}button,a{background:#08766f;color:#fff;border:0;border-radius:7px;padding:11px 14px;font-weight:bold;text-decoration:none}.msg{padding:12px;background:#edf6f5;border-radius:7px;margin-bottom:13px}</style></head><body><main class="card"><p><a href="alumni-community.php">Member sign in</a></p><h1>Claim your alumni profile</h1><p>For old students whose school record was imported into the Alumni Hub.</p><?php if($message){?><p class="msg"><?php echo alumni_safe($message);?></p><?php }?><?php if($stage==='find'){?><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe(alumni_csrf_token());?>"><label>Registered phone or email</label><input name="identity" required><button name="request_code">Send access code</button></form><?php }else{?><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe(alumni_csrf_token());?>"><label>Six-digit access code</label><input name="code" inputmode="numeric" required><label>Create password</label><input type="password" name="password" minlength="8" required><button name="claim_profile">Activate my account</button></form><?php }?></main></body></html>
